def _clock():
    t = "".join(f'<line x1="{100 + 78 * math.sin(math.radians(a)):.1f}" y1="{100 - 78 * math.cos(math.radians(a)):.1f}" x2="{100 + 94 * math.sin(math.radians(a)):.1f}" y2="{100 - 94 * math.cos(math.radians(a)):.1f}" stroke="#BBD3F5" stroke-width="6" stroke-linecap="round"/>' for a in range(0, 360, 30))
    svg = f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200">{t}<line x1="100" y1="100" x2="168" y2="100" stroke="#fff" stroke-width="4" stroke-linecap="round"/><line x1="100" y1="100" x2="160" y2="65" stroke="#fff" stroke-width="4" stroke-linecap="round"/><circle cx="100" cy="100" r="7" fill="#0A2540" stroke="#fff" stroke-width="4"/></svg>'
    return "<img src='data:image/svg+xml;base64," + base64.b64encode(svg.encode()).decode() + "' alt=''>"


