# ---------------------------------------------------------------- fictional data
N_NAMES = ["Margarida Santos", "António Ferreira", "Helena Duarte", "Joaquim Pereira", "Luísa Carvalho", "Manuel Almeida",
           "Teresa Rocha", "Fernando Lopes", "Isabel Moreira", "Rui Nogueira", "Amélia Costa", "Carlos Mendes", "Beatriz Silva", "Armando Reis"]
I_NAMES = ["Eleanor Whitfield", "Henrik Larsen", "Sofia Marchetti", "Walter Brandt", "Ingrid Solheim", "Pierre Dubois", "Marta Kowalska",
           "Oskar Lindqvist", "Clara Van den Berg", "George Hallam", "Nadia Haddad", "Tomás Beltrán", "Agnes Fischer", "Louis Moreau"]
CITIES = ["Bergen", "Lyon", "Utrecht", "Leeds", "Turin", "Gdańsk", "Malmö"]
PROS = (["Nurse Ana Ribeiro", "Nurse Paulo Matos", "Dr. Sónia Lima"] if NH else ["Case manager J. Moreau", "Nurse L. Becker", "Coordinator M. Rossi"])
STATES = ["Normal"] * 7 + ["Attention required"] * 3 + ["Critical"] * 2 + ["No recent data"] * 2


def series(rng, state):
    idx = pd.date_range(NOW - timedelta(days=13), NOW, freq="6h"); n = len(idx); t = np.arange(n)
    ramp = np.clip((t - n + 12) / 12, 0, 1)
    hr = rng.normal(72, 5) + rng.normal(0, 3, n) + 2 * np.sin(t * np.pi / 2)
    sp = rng.normal(97.3, .4) + rng.normal(0, .6, n)
    sy = rng.normal(116, 6) + rng.normal(0, 5, n); di = sy * .6 + rng.normal(0, 3, n)
    hv = rng.normal(38, 5) + rng.normal(0, 4, n)
    k = {"Attention required": (24, 3.2, 18, 6), "Critical": (46, 6.5, 30, 24)}.get(state, (0, 0, 0, 0))
    hr, sp, sy, hv = hr + k[0] * ramp, sp - k[1] * ramp, sy + k[2] * ramp, hv - k[3] * ramp
    df = pd.DataFrame(dict(time=idx, HR=hr.round(), SpO2=np.minimum(sp, 100).round(1), SYS=sy.round(), DIA=di.round(), HRV=hv.round()))
    return df[df.time < NOW - timedelta(days=3)] if state == "No recent data" else df


@st.cache_data
def load(nh):
    rng = np.random.default_rng(3 if nh else 5)
    names, states = (N_NAMES if nh else I_NAMES), list(STATES); rng.shuffle(states)
    rows, ts = [], {}
    for i, (nm, st_) in enumerate(zip(names, states)):
        s = series(rng, st_); ts[nm] = s; l = s.iloc[-1]; hrs = int((NOW - l.time).total_seconds() // 3600)
        mon = {"No recent data": "Offline", "Critical": "Connected"}.get(st_, "Intermittent" if i % 5 == 0 else "Connected")
        rows.append({"Name": nm, "Age": int(rng.integers(74, 93)), "Location": f"Room {100 * (1 + i // 5) + i % 5 + 1}" if nh else CITIES[i % 7],
                     "Monitoring status": mon, "Latest measurement": f"Heart rate {l.HR:.0f} bpm · Oxygen {l.SpO2:.0f}% · Blood pressure {l.SYS:.0f}/{l.DIA:.0f} · {hrs} h ago",
                     "Alert status": st_, "Last nursing visit": (NOW - timedelta(days=int(rng.integers(1, 21)))).strftime("%d %b"),
                     "Care level": f"Level {int(rng.integers(1, 4))}", "Device": "Atempo wrist band",
                     "Contact": ["Daughter", "Son", "Spouse", "Niece"][i % 4], "Enrolled": f"{['Jan', 'Mar', 'Jun', 'Sep'][i % 4]} 2025"})
    P = pd.DataFrame(rows)
    ty = {"Critical": ["Heart rate", "Blood oxygen", "Blood pressure"], "Attention required": ["Heart rate", "Blood pressure", "Heart rate variability"], "No recent data": ["Device sync"], "Normal": ["Heart rate variability", "Heart rate"]}
    al = []
    for _, r in P.iterrows():
        for j in range(2 if r["Alert status"] != "Normal" else int(rng.integers(0, 2))):
            s_ = r["Alert status"]
            al.append({"Priority": {"Critical": "High", "Attention required": "Medium"}.get(s_, "Low"), "Person": r.Name, "Measurement": str(rng.choice(ty[s_])),
                       "Date & time": NOW - timedelta(hours=int(rng.integers(1, 70))),
                       "Status": str(rng.choice(["Open", "Open", "In review"] if j == 0 and s_ != "Normal" else ["Resolved", "In review"])),
                       "Assigned to": PROS[int(rng.integers(0, 3))]})
    A = pd.DataFrame(al).sort_values("Date & time", ascending=False).reset_index(drop=True)
    A["Date & time"] = A["Date & time"].dt.strftime("%d %b, %H:%M")
    tasks = ["Review measurement trend with care team", "Confirm device is worn overnight", "Family check-in call", "Schedule nursing visit", "Update care notes"]
    F = pd.DataFrame([{"Person": names[i * 2 % 14], "Task": tasks[i % 5], "Due": (NOW + timedelta(days=i - 2)).strftime("%d %b"),
                       "Owner": PROS[i % 3], "Status": ["Overdue", "Due soon", "Scheduled", "Scheduled", "Completed", "Due soon", "Scheduled"][i]} for i in range(7)])
    V = pd.DataFrame([{"Date": (NOW - timedelta(days=int(d))).strftime("%d %b"), "Policyholder": names[(i * 3) % 14], "Nurse": PROS[1 + i % 2],
                       "Visit type": ["Scheduled follow-up", "Alert-prompted check", "Routine home visit"][i % 3], "Status": "Completed"}
                      for i, d in enumerate(sorted(rng.integers(0, 28, 9)))])
    return P, ts, A, F, V


P, TS, A, F, V = load(NH)
AKEY = "alerts_nh" if NH else "alerts_ins"
if AKEY not in st.session_state: st.session_state[AKEY] = A.copy()
A = st.session_state[AKEY]; st.session_state["akey"] = AKEY
NAMES = list(P.Name)
if FAM:
    FAM_NAME = P[P["Alert status"] == "Attention required"].Name.iloc[0]; FR = P[P.Name == FAM_NAME].iloc[0]
    USER = {"Daughter": "Inês", "Son": "Pedro", "Spouse": "Maria", "Niece": "Rita"}[FR.Contact] + " " + FAM_NAME.split()[-1]; ORG = f"{FR.Contact} of {FAM_NAME}"
PILL = f"Family portal · {FAM_NAME}" if FAM else f"{seg_label} · {ORG}"


# ---------------------------------------------------------------- helpers
def badge(t):
    c = COL.get(t, GREY); k = " pulse" if t in ("Critical", "Open") else ""
    return f'<span class="b{k}" style="background:{c}22;color:{c}">● {t}</span>'


def table(df, badges=("Monitoring status", "Alert status", "Priority", "Status")):
    h = "<div class='tw'><table><tr>" + "".join(f"<th>{c}</th>" for c in df.columns) + "</tr>"
    for _, r in df.iterrows():
        h += "<tr>" + "".join(f"<td>{badge(r[c]) if c in badges else r[c]}</td>" for c in df.columns) + "</tr>"
    st.markdown(h + "</table></div>", unsafe_allow_html=True)


def kpi(col, label, val, sub="", color=NAVY):
    col.markdown(f"<div class='card kpi'><div class='kl'>{label}</div><div class='kv' style='color:{color}'>{val}</div><div class='ks'>{sub}</div></div>", unsafe_allow_html=True)


def head(title, sub):
    st.markdown(f"<div class='hero'><div class='over'>{PILL}</div><h1>{title}</h1><p>{sub}</p>{CLOCK}</div>", unsafe_allow_html=True)


def sec(t, s=""):
    st.markdown(f"#### {t}")
    if s: st.caption(s)


def show(fig, h=290, title=None, xt=None, yt=None, keep=False, r=8):
    fig.update_layout(height=h, margin=dict(l=8, r=r, t=60 if title else 24, b=8), title=dict(text=title, x=0, font=dict(size=15)) if title else None, paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
                      font=dict(family="Manrope", color=NAVY, size=13), hovermode="x unified", hoverlabel=dict(bgcolor="#FFFFFF", bordercolor=LINE, font=dict(color=NAVY)), legend=dict(orientation="h", y=-.2, title=None))
    ax = dict(showline=True, linecolor=AX, linewidth=2, ticks="outside", tickcolor=AX, tickfont=dict(color=AX, size=12), title_font=dict(color=AX, size=12))
    fig.update_xaxes(showgrid=False, **ax); fig.update_yaxes(gridcolor="#DCE6F5", **ax)
    if not keep: fig.update_xaxes(title=xt); fig.update_yaxes(title=yt)
    st.plotly_chart(fig, use_container_width=True, theme=None)


def go_profile(n):
    st.session_state.nav, st.session_state.person = NAV[1], n


def zone(c, v):
    for y0, y1, col in META[c]["z"]:
        if v < y1: return col
    return META[c]["z"][-1][2]


def metric_chart(df, c, h=340):
    m = META[c]; d = df.set_index("time").resample("D").mean(numeric_only=True).reset_index()
    ids = [("SYS", "Systolic (top number)"), ("DIA", "Diastolic (bottom number)")] if c == "SYS" else [(c, m["title"])]
    fig = make_subplots(rows=len(ids), cols=1, shared_xaxes=True, vertical_spacing=.1)
    for i, (k, name) in enumerate(ids, 1):
        mk = META[k]; span = mk["ymax"] - mk["ymin"]
        for y0, y1, col in mk["z"]:
            fig.add_hrect(y0=y0, y1=y1, fillcolor=col, opacity=.13, line_width=0, row=i, col=1)
            if (min(y1, mk["ymax"]) - y0) / span >= .12:
                fig.add_annotation(x=1.01, xref="paper", y=(y0 + min(y1, mk["ymax"])) / 2, yref="y" if i == 1 else f"y{i}", text=LBL[col], showarrow=False, xanchor="left", font=dict(size=10, color=col))
        fig.add_trace(go.Scatter(x=df.time, y=df[k], mode="lines", line=dict(color=NAVY, width=1), opacity=.25, showlegend=False, hoverinfo="skip"), row=i, col=1)
        v = d[k].round(1)
        fig.add_trace(go.Scatter(x=d.time, y=v, mode="lines+markers", showlegend=False, line=dict(color=NAVY, width=2.5),
                                 marker=dict(size=9, color=[zone(k, x) for x in v], line=dict(color="#fff", width=2)),
                                 hovertemplate="%{y} " + mk["u"] + "<extra>" + name + "</extra>"), row=i, col=1)
        fig.update_yaxes(range=[mk["ymin"], mk["ymax"]], title_text=(name.split(" (")[0] + " (" + mk["u"] + ")") if c == "SYS" else m["unit"], row=i, col=1)
    fig.update_xaxes(tickformat="%d %b")
    show(fig, int(h * 1.2) if c == "SYS" else h, f"<b>{'Blood pressure' if c == 'SYS' else m['title']}</b> · daily average", keep=True, r=95)
    last = df.iloc[-1]; old = last.time < NOW - timedelta(hours=48)
    chips = " ".join(f"<span class='b' style='background:{zone(k, last[k])}22;color:{zone(k, last[k])}'>● {n.split(' (')[0]} {last[k]:.0f} {META[k]['u']} – {LBL[zone(k, last[k])]}</span>" for k, n in ids)
    st.markdown(chips + (f" <span class='ks'>last measured {last.time.strftime('%d %b')}</span>" if old else ""), unsafe_allow_html=True); st.caption(m["note"])


def vitals_row(l):
    c = st.columns(4)
    for col, (lab, v, u, chk) in zip(c, [("Heart rate", f"{l.HR:.0f}", "bpm", [("HR", l.HR)]), ("Blood oxygen", f"{l.SpO2:.0f}", "%", [("SpO2", l.SpO2)]),
                                          ("Blood pressure", f"{l.SYS:.0f}/{l.DIA:.0f}", "mmHg", [("SYS", l.SYS), ("DIA", l.DIA)]), ("Heart rate variability", f"{l.HRV:.0f}", "ms", [("HRV", l.HRV)])]):
        w = max((zone(k, x) for k, x in chk), key=RANK.get)
        kpi(col, lab, f"{v} <small>{u}</small>", f"<span class='b' style='background:{w}22;color:{w}'>● {LBL[w]}</span>")


def readings(n):
    l = TS[n].iloc[-1]; a = int((NOW - l.time).total_seconds() // 3600); a = f"{a} h ago" if a < 48 else f"{a // 24} days ago"
    dot = lambda col: f"<span style='color:{col}'>●</span>"
    bp = max(zone("SYS", l.SYS), zone("DIA", l.DIA), key=RANK.get)
    return f"{dot(zone('HR', l.HR))} Heart rate {l.HR:.0f} bpm &nbsp; {dot(zone('SpO2', l.SpO2))} Oxygen {l.SpO2:.0f}% &nbsp; {dot(bp)} Blood pressure {l.SYS:.0f}/{l.DIA:.0f}<br><span class='ks'>Measured {a}</span>"


