def people_list(key, visit=True, filters=False):
    D = P
    if filters:
        f1, f2 = st.columns([3, 2])
        q = f1.text_input("Search", key=f"{key}_q", placeholder="Search by name…", label_visibility="collapsed")
        sf = f2.selectbox("Status", ["All statuses", "Normal", "Attention required", "Critical", "No recent data"], key=f"{key}_s", label_visibility="collapsed")
        if q: D = D[D.Name.str.contains(q, case=False)]
        if sf != "All statuses": D = D[D["Alert status"] == sf]
    w = [2.4, .8, 1.1, 1.5, 3.6, 1.6] + ([1.0] if visit else [])
    with st.container(border=True):
        for x, t in zip(st.columns(w), ["Name", "Age", "Room" if NH else "City", "Monitoring", "Latest measurement", "Alert status", "Last visit"]): x.markdown(f"<span class='ks'><b>{t}</b></span>", unsafe_allow_html=True)
        if D.empty: st.markdown("No one matches this search.")
        for _, r in D.iterrows():
            c = st.columns(w, vertical_alignment="center")
            c[0].button(r.Name, key=f"{key}_{r.Name}", type="tertiary", on_click=go_profile, args=(r.Name,))
            c[1].write(r.Age); c[2].write(r.Location); c[3].markdown(badge(r["Monitoring status"]), unsafe_allow_html=True)
            c[4].markdown(readings(r.Name), unsafe_allow_html=True); c[5].markdown(badge(r["Alert status"]), unsafe_allow_html=True)
            if visit: c[6].write(r["Last nursing visit"])


def pop():
    return pd.concat(TS.values()).groupby("time").mean(numeric_only=True).reset_index()


def coverage():
    days = pd.date_range(NOW.date() - timedelta(days=13), NOW.date())
    return pd.DataFrame({"Day": days, "Coverage %": [100 * sum((d.time.dt.date == x.date()).any() for d in TS.values()) / len(TS) for x in days]})


