def live_view(n):
    base = float(TS[n].iloc[-1].HR); buf = st.session_state.setdefault("live_" + n, [base] * 40)
    buf.append(float(np.clip(buf[-1] + np.random.normal(0, 1.8) + (base - buf[-1]) * .15, 45, 135))); del buf[:-40]
    fig = go.Figure(); fig.add_hrect(y0=60, y1=100, fillcolor=GREEN, opacity=.12, line_width=0)
    fig.add_trace(go.Scatter(y=buf, mode="lines", line=dict(color=ACC, width=3, shape="spline"), hovertemplate="%{y:.0f} bpm<extra></extra>"))
    fig.update_yaxes(range=[40, 140]); fig.update_xaxes(showticklabels=False)
    show(fig, 260, f"<b>Live heart rate</b> · {n}", yt="beats per minute")
    v = buf[-1]; c = zone("HR", v)
    st.markdown(f"<span class='b' style='background:{c}22;color:{c}'>● {v:.0f} bpm – {LBL[c]}</span> <span class='ks'>Simulated stream for the demo · updates every 2 seconds</span>", unsafe_allow_html=True)


